/**
 * The help of the running build: the section that names the exchange folder gets the path
 * this variant actually uses.
 */
internal fun helpSections(exchangePath: String): List<HelpSection> = detailedHelpSections.map { section ->
    section.copy(blocks = section.blocks.map { it.withExchangePath(exchangePath) })
}

private fun HelpBlock.withExchangePath(exchangePath: String): HelpBlock = when (this) {
    is HelpBlock.Paragraph -> copy(text = text.replace(EXCHANGE_PATH_TOKEN, exchangePath))
    is HelpBlock.Steps -> copy(items = items.map { it.replace(EXCHANGE_PATH_TOKEN, exchangePath) })
    is HelpBlock.Bullets -> copy(items = items.map { it.replace(EXCHANGE_PATH_TOKEN, exchangePath) })
    is HelpBlock.Note -> copy(text = text.replace(EXCHANGE_PATH_TOKEN, exchangePath))
    is HelpBlock.Preformatted -> copy(text = text.replace(EXCHANGE_PATH_TOKEN, exchangePath))
    is HelpBlock.Visual -> this
}
